import './App.css';
import OnlineMenu from './components/OnlineMenu';
import Layout from './Layout';
import { HashRouter as Router, Routes, Route } from 'react-router';


function App() {
  return (
    <Router>
    <Routes>
    <Route path='/' element={<Layout />} />
    <Route path='/OnlineMenu' element={<OnlineMenu />} />
    </Routes>
    </Router>
  );
}

export default App;
